import requests

def main():
    url = "http://crypto.csaw.io/rsa/decrypt"
    data = b"Test data"
    print(f"Sending: {data}")

    try:
        req = requests.post(url=url, data=data)
        print(f"Status code: {req.status_code}")
        print(f"Response: {req.content}")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()

import re

# The hexadecimal plaintext we got from our RSA solution
hex_string = ''

# Convert the hex to bytes
plaintext_bytes = bytes.fromhex(hex_string)

# Search for the flag format in the binary data
flag_pattern = re.compile(b'csawctf{.*?}')
matches = flag_pattern.findall(plaintext_bytes)

if matches:
    for match in matches:
        print(f"Found flag: {match.decode('utf-8')}")
else:
    print("No flag pattern found in the exact format")

# Try to extract ASCII characters to see if there might be a flag in plain text
printable_chars = ''.join(chr(b) if 32 <= b <= 126 else '.' for b in plaintext_bytes)
print(f"Printable characters in the plaintext: {printable_chars}")

# Try to find flag-like patterns
for i in range(len(plaintext_bytes) - 7):
    # Look for 'c' followed by potential flag characters
    if plaintext_bytes[i] == ord('c'):
        potential_flag = plaintext_bytes[i:i+50]  # Arbitrary length to capture flag
        try:
            potential_flag_str = potential_flag.decode('utf-8')
            if 'csaw' in potential_flag_str:
                print(f"Potential flag at position {i}: {potential_flag_str}")
        except UnicodeDecodeError:
            continue

# Also check each byte offset (in case of padding or alignment issues)
for offset in range(1, 8):
    aligned_bytes = plaintext_bytes[offset:]
    try:
        text = aligned_bytes.decode('utf-8', errors='ignore')
        if 'csaw' in text:
            print(f"Found 'csaw' with offset {offset}: {text}")
    except:
        pass
